private static String substituteVariables(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int start = 0;
    int end;
    while ((start = value.indexOf("${", start)) != -1) {
        end = value.indexOf("}", start);
        if (end == -1) {
            break; // No closing brace found, treat as literal
        }
        result.append(value, start + 2, end);
        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        } else {
            result.append("${").append(varName).append("}"); // Keep original if not found
        }
        start = end + 1;
    }
    result.append(value.substring(start));
    return result.toString();
}

