protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Assuming we need to create a path from the edges in the tour
    // We will use a simple implementation that assumes the graph is connected
    // and the tour is a valid Eulerian circuit or Hamiltonian cycle.

    if (tour == null || tour.isEmpty()) {
        return null; // or throw an exception based on your requirements
    }

    // Create a list to store the vertices of the path
    List<V> pathVertices = new ArrayList<>();

    // Start with an arbitrary edge from the tour
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    pathVertices.add(startVertex);

    // Remove the start edge from the tour to avoid revisiting it
    Set<E> remainingEdges = new HashSet<>(tour);
    remainingEdges.remove(startEdge);

    // Current vertex is the target of the start edge
    V currentVertex = graph.getEdgeTarget(startEdge);

    // Traverse the graph using the edges in the tour
    while (!remainingEdges.isEmpty()) {
        // Find an edge in the tour that starts from the current vertex
        E nextEdge = null;
        for (E edge : remainingEdges) {
            if (graph.getEdgeSource(edge).equals(currentVertex)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            // If no such edge is found, the tour is not valid
            return null; // or throw an exception based on your requirements
        }

        // Add the target vertex of the next edge to the path
        currentVertex = graph.getEdgeTarget(nextEdge);
        pathVertices.add(currentVertex);

        // Remove the next edge from the remaining edges
        remainingEdges.remove(nextEdge);
    }

    // Create and return the graph path
    return new GraphPathImpl<>(graph, pathVertices.get(0), pathVertices.get(pathVertices.size() - 1), pathVertices, tour);
}

