private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    int length = input.length();
    for (int i = 0; i < length; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < length) {
                char nextChar = input.charAt(i + 1);
                if (nextChar == 'u') {
                    // Handle Unicode escape sequence
                    if (i + 5 < length) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            int codePoint = Integer.parseInt(hex, 16);
                            output.append((char) codePoint);
                            i += 5; // Skip the hex digits
                        } catch (NumberFormatException e) {
                            // Invalid Unicode escape, treat as literal
                            output.append('\\').append('u').append(hex);
                            i += 5; // Skip the hex digits
                        }
                    } else {
                        // Not enough characters for a Unicode escape
                        output.append('\\').append('u');
                        i += 1; // Skip the 'u'
                    }
                } else {
                    // Handle other escape sequences
                    switch (nextChar) {
                        case 'b':
                            output.append('\b');
                            break;
                        case 't':
                            output.append('\t');
                            break;
                        case 'n':
                            output.append('\n');
                            break;
                        case 'f':
                            output.append('\f');
                            break;
                        case 'r':
                            output.append('\r');
                            break;
                        case '"':
                            output.append('"');
                            break;
                        case '\'':
                            output.append('\'');
                            break;
                        case '\\':
                            output.append('\\');
                            break;
                        default:
                            // Treat as literal
                            output.append('\\').append(nextChar);
                            break;
                    }
                    i += 1; // Skip the escaped character
                }
            } else {
                // Trailing backslash, treat as literal
                output.append('\\');
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

